// Validate competitor domain analyzer input
try {
  const body = $input.item.json.body || $input.item.json;

  // Validate domain
  if (!body.domain || typeof body.domain !== 'string') {
    throw new Error('Invalid input: domain is required and must be a string');
  }

  // Clean domain (remove protocol, www, trailing slashes)
  let domain = body.domain.trim()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/$/, '')
    .split('/')[0]; // Take only hostname

  if (domain.length === 0) {
    throw new Error('Invalid input: domain cannot be empty after cleaning');
  }

  // Validate domain format (basic)
  if (!domain.includes('.')) {
    throw new Error('Invalid input: domain must contain at least one dot (e.g., example.com)');
  }

  // Validate maxKeywords
  let maxKeywords = 200; // default
  if (body.maxKeywords !== undefined) {
    const parsed = parseInt(body.maxKeywords);
    if (isNaN(parsed) || parsed < 1) {
      throw new Error('Invalid input: maxKeywords must be a positive number');
    }
    maxKeywords = Math.min(parsed, 500); // cap at 500
  }

  // Validate depth
  let depth = 20; // default
  if (body.depth !== undefined) {
    const parsed = parseInt(body.depth);
    if (isNaN(parsed) || parsed < 1) {
      throw new Error('Invalid input: depth must be a positive number');
    }
    depth = Math.min(parsed, 100); // cap at 100
  }

  // Validate batchSize
  let batchSize = 3; // default
  if (body.batchSize !== undefined) {
    const parsed = parseInt(body.batchSize);
    if (!isNaN(parsed) && parsed >= 1 && parsed <= 10) {
      batchSize = parsed;
    }
  }

  // Validate batchDelay
  let batchDelay = 2000; // default
  if (body.batchDelay !== undefined) {
    const parsed = parseInt(body.batchDelay);
    if (!isNaN(parsed) && parsed >= 0 && parsed <= 10000) {
      batchDelay = parsed;
    }
  }

  return {
    domain: domain,
    maxKeywords: maxKeywords,
    depth: depth,
    batchSize: batchSize,
    batchDelay: batchDelay,
    location: body.location || 'us',
    language: body.language || 'en',
    timestamp: new Date().toISOString()
  };

} catch (error) {
  throw new Error(`Validation failed: ${error.message}`);
}

// Process and filter extracted competitor keywords
try {
  const serpData = $input.item.json;
  const config = $('Validate Input').item.json;
  const organicResults = serpData.organic_results || [];

  if (organicResults.length === 0) {
    throw new Error(`No ranking keywords found for domain: ${config.domain}`);
  }

  // Extract keywords from organic results
  // Note: SerpAPI site: search returns pages, we need to infer keywords from titles/snippets
  // For better results, consider using DataForSEO or SEMrush API in production

  const extractedKeywords = [];
  const keywordSet = new Set();

  organicResults.forEach((result, index) => {
    // Extract potential keywords from title and snippet
    const title = (result.title || '').toLowerCase();
    const snippet = (result.snippet || '').toLowerCase();
    const link = result.link || '';
    const position = result.position || index + 1;

    // Simple keyword extraction from title (split by common separators)
    const titleWords = title.split(/[|\-–—:•]/).map(s => s.trim()).filter(s => s.length > 3);

    titleWords.forEach(keyword => {
      // Basic filtering
      if (keyword.length > 200) return;
      if (keyword.length < 3) return;
      if (/^[0-9]+$/.test(keyword)) return; // Skip pure numbers

      const normalizedKeyword = keyword.trim();
      if (!keywordSet.has(normalizedKeyword)) {
        keywordSet.add(normalizedKeyword);
        extractedKeywords.push({
          keyword: normalizedKeyword,
          source_url: link,
          ranking_position: position,
          source: 'serp_title'
        });
      }
    });

    // Also use the full title as a keyword if it's reasonable length
    if (title.length > 3 && title.length <= 200 && !keywordSet.has(title)) {
      keywordSet.add(title);
      extractedKeywords.push({
        keyword: title,
        source_url: link,
        ranking_position: position,
        source: 'full_title'
      });
    }
  });

  // Limit to maxKeywords
  const limitedKeywords = extractedKeywords.slice(0, config.maxKeywords);

  if (limitedKeywords.length === 0) {
    throw new Error('No valid keywords extracted from competitor domain');
  }

  return {
    domain: config.domain,
    totalPagesFound: organicResults.length,
    totalKeywordsExtracted: limitedKeywords.length,
    keywords: limitedKeywords.map(k => k.keyword),
    keywordDetails: limitedKeywords,
    depth: config.depth,
    batchSize: config.batchSize,
    batchDelay: config.batchDelay,
    location: config.location,
    language: config.language,
    timestamp: config.timestamp
  };

} catch (error) {
  throw new Error(`Keyword extraction failed: ${error.message}`);
}

// Split keywords into individual items for SCO analysis
const data = $input.item.json;
const keywords = data.keywords || [];

return keywords.map((keyword, index) => {
  const details = data.keywordDetails[index] || {};
  return {
    keyword: keyword,
    competitorDomain: data.domain,
    rankingPosition: details.ranking_position || null,
    sourceUrl: details.source_url || null,
    depth: data.depth,
    location: data.location,
    language: data.language,
    batchSize: data.batchSize,
    batchDelay: data.batchDelay,
    totalKeywords: keywords.length,
    timestamp: data.timestamp
  };
});

// Process SERP data and perform gap analysis (same as bulk workflow)
try {
  const serpData = $input.item.json;
  const keyword = $('Batch Processor').item.json.keyword;
  const competitorDomain = $('Batch Processor').item.json.competitorDomain;
  const rankingPosition = $('Batch Processor').item.json.rankingPosition;
  const depth = $('Batch Processor').item.json.depth;

  const organicResults = serpData.organic_results || [];
  const relatedSearches = serpData.related_searches || [];
  const relatedQuestions = serpData.related_questions || [];

  // Process SERP overview
  const serpOverview = organicResults.map((result, index) => {
    let domain = '';
    try {
      if (result.link) {
        domain = new URL(result.link).hostname.replace('www.', '');
      }
    } catch (e) {
      domain = result.displayed_link || 'unknown';
    }

    return {
      rank: index + 1,
      title: result.title || '',
      snippet: result.snippet || '',
      link: result.link || '',
      domain: domain,
      isCompetitor: domain === competitorDomain || domain.includes(competitorDomain)
    };
  });

  // Find competitor's ranking
  const competitorRanking = serpOverview.find(s => s.isCompetitor);
  const actualPosition = competitorRanking ? competitorRanking.rank : null;

  // Extract related keywords
  const relatedKeywords = [];

  relatedSearches.forEach(item => {
    if (item.query) {
      relatedKeywords.push({
        keyword: item.query,
        source: 'related_search'
      });
    }
  });

  relatedQuestions.forEach(item => {
    if (item.question) {
      relatedKeywords.push({
        keyword: item.question,
        source: 'people_also_ask'
      });
    }
  });

  // Calculate authority metrics
  const domainCounts = {};
  serpOverview.forEach(item => {
    domainCounts[item.domain] = (domainCounts[item.domain] || 0) + 1;
  });

  const highAuthorityDomains = [
    'wikipedia.org', 'youtube.com', 'amazon.com', 'facebook.com',
    'linkedin.com', 'twitter.com', 'instagram.com', 'reddit.com',
    'quora.com', 'pinterest.com', 'medium.com', 'forbes.com',
    'nytimes.com', 'washingtonpost.com', 'bbc.com', 'cnn.com'
  ];

  const authorityCount = serpOverview.filter(item => 
    highAuthorityDomains.some(domain => item.domain.includes(domain))
  ).length;

  const authorityMetrics = {
    highAuthorityCount: authorityCount,
    uniqueDomains: Object.keys(domainCounts).length,
    totalResults: serpOverview.length,
    domainConcentration: serpOverview.length > 0 ? Math.max(...Object.values(domainCounts)) / serpOverview.length : 0,
    competitorPresent: !!competitorRanking,
    competitorPosition: actualPosition
  };

  // Content theme analysis
  const contentThemes = {};
  const patterns = [
    { name: 'how-to', keywords: ['how to', 'guide', 'tutorial', 'step', 'learn', 'instructions'] },
    { name: 'comparison', keywords: ['vs', 'versus', 'compare', 'best', 'top', 'review'] },
    { name: 'pricing', keywords: ['price', 'cost', 'pricing', 'cheap', 'expensive', 'affordable', 'free'] },
    { name: 'definition', keywords: ['what is', 'definition', 'meaning', 'explain', 'overview'] },
    { name: 'list', keywords: ['list', 'types', 'kinds', 'examples', 'ways'] },
    { name: 'location', keywords: ['near me', 'location', 'where', 'local', 'nearby'] },
    { name: 'reviews', keywords: ['review', 'rating', 'testimonial', 'customer', 'feedback'] },
    { name: 'benefits', keywords: ['benefit', 'advantage', 'why', 'reason', 'pros'] }
  ];

  serpOverview.forEach(item => {
    const content = `${item.title} ${item.snippet}`.toLowerCase();
    patterns.forEach(pattern => {
      if (pattern.keywords.some(kw => content.includes(kw))) {
        contentThemes[pattern.name] = (contentThemes[pattern.name] || 0) + 1;
      }
    });
  });

  // Identify content gaps
  const totalResults = serpOverview.length;
  const missingSubtopics = [];
  const thinContentAreas = [];

  patterns.forEach(pattern => {
    const count = contentThemes[pattern.name] || 0;
    const coverage = totalResults > 0 ? (count / totalResults) * 100 : 0;

    if (coverage === 0) {
      missingSubtopics.push({
        theme: pattern.name,
        coverage: 0,
        opportunity: 'high'
      });
    } else if (coverage < 20) {
      thinContentAreas.push({
        theme: pattern.name,
        coverage: parseFloat(coverage.toFixed(1)),
        opportunity: 'medium'
      });
    }
  });

  return {
    keyword: keyword,
    competitorDomain: competitorDomain,
    expectedPosition: rankingPosition,
    actualPosition: actualPosition,
    positionVerified: actualPosition === rankingPosition,
    depth: depth,
    serpOverview: serpOverview,
    relatedKeywords: relatedKeywords,
    authorityMetrics: authorityMetrics,
    contentGaps: {
      missingSubtopics: missingSubtopics,
      thinContentAreas: thinContentAreas,
      contentThemes: contentThemes
    }
  };

} catch (error) {
  // Return error result for this keyword
  return {
    keyword: $('Batch Processor').item.json.keyword,
    competitorDomain: $('Batch Processor').item.json.competitorDomain,
    error: true,
    errorMessage: error.message,
    serpOverview: [],
    relatedKeywords: [],
    authorityMetrics: {},
    contentGaps: {}
  };
}

// Calculate difficulty and opportunity scores
try {
  const data = $input.item.json;

  // Skip if error
  if (data.error) {
    return {
      ...data,
      difficultyScore: null,
      opportunityScore: null,
      priority: 'Error'
    };
  }

  const serpOverview = data.serpOverview || [];
  const authorityMetrics = data.authorityMetrics || {};
  const contentGaps = data.contentGaps || {};
  const competitorPresent = authorityMetrics.competitorPresent || false;
  const competitorPosition = authorityMetrics.competitorPosition || null;

  // === DIFFICULTY SCORE (0-100) ===
  let difficultyScore = 0;

  const highAuthorityRatio = authorityMetrics.highAuthorityCount / Math.max(authorityMetrics.totalResults, 1);
  difficultyScore += highAuthorityRatio * 35;

  const concentration = authorityMetrics.domainConcentration || 0;
  if (concentration > 0.3) {
    difficultyScore += 25;
  } else if (concentration > 0.15) {
    difficultyScore += 15;
  } else {
    difficultyScore += 5;
  }

  const saturatedThemes = Object.keys(contentGaps.contentThemes || {}).length;
  difficultyScore += Math.min(saturatedThemes * 2, 20);

  difficultyScore += 12; // Default intent competition

  difficultyScore = Math.min(Math.round(difficultyScore), 100);

  // === OPPORTUNITY SCORE (0-100) ===
  let opportunityScore = 0;

  const missingCount = (contentGaps.missingSubtopics || []).length;
  const thinCount = (contentGaps.thinContentAreas || []).length;
  opportunityScore += Math.min(missingCount * 8 + thinCount * 4, 35);

  const keywordCount = (data.relatedKeywords || []).length;
  opportunityScore += Math.min(keywordCount * 1.5, 25);

  opportunityScore += 18; // Default intent alignment

  if (difficultyScore < 35) {
    opportunityScore += 15;
  } else if (difficultyScore < 55) {
    opportunityScore += 10;
  } else if (difficultyScore < 70) {
    opportunityScore += 5;
  }

  // Bonus if competitor ranks but position is weak
  if (competitorPresent && competitorPosition > 5) {
    opportunityScore += 10; // They rank but not well - opportunity to outrank
  }

  opportunityScore = Math.min(Math.round(opportunityScore), 100);

  // === PRIORITY ===
  let priority = 'Low';
  const combinedScore = opportunityScore - (difficultyScore * 0.65);

  if (combinedScore > 35 && opportunityScore > 65) {
    priority = 'High';
  } else if (combinedScore > 15 && opportunityScore > 45) {
    priority = 'Medium';
  }

  // Competitive insight
  let competitiveInsight = 'Not ranking';
  if (competitorPresent) {
    if (competitorPosition <= 3) {
      competitiveInsight = 'Strong - Top 3';
    } else if (competitorPosition <= 10) {
      competitiveInsight = 'Moderate - Page 1';
    } else {
      competitiveInsight = 'Weak - Page 2+';
    }
  }

  return {
    ...data,
    difficultyScore: difficultyScore,
    opportunityScore: opportunityScore,
    priority: priority,
    combinedScore: parseFloat(combinedScore.toFixed(2)),
    competitiveInsight: competitiveInsight
  };

} catch (error) {
  return {
    ...data,
    difficultyScore: null,
    opportunityScore: null,
    priority: 'Error',
    scoringError: error.message
  };
}

// Aggregate all competitor keyword analysis results
const allResults = $input.all();
const config = $('Process & Filter Keywords').item.json;

const successful = [];
const failed = [];

allResults.forEach(item => {
  const data = item.json;
  if (data.error) {
    failed.push({
      keyword: data.keyword,
      error: data.errorMessage || data.scoringError || 'Unknown error'
    });
  } else {
    successful.push(data);
  }
});

// Ranking analysis
const rankingDistribution = {
  top3: 0,
  top10: 0,
  page2: 0,
  notRanking: 0
};

successful.forEach(result => {
  const pos = result.actualPosition;
  if (!pos) {
    rankingDistribution.notRanking++;
  } else if (pos <= 3) {
    rankingDistribution.top3++;
  } else if (pos <= 10) {
    rankingDistribution.top10++;
  } else {
    rankingDistribution.page2++;
  }
});

// Aggregate metrics
const avgDifficulty = successful.length > 0 
  ? successful.reduce((sum, r) => sum + (r.difficultyScore || 0), 0) / successful.length 
  : 0;

const avgOpportunity = successful.length > 0
  ? successful.reduce((sum, r) => sum + (r.opportunityScore || 0), 0) / successful.length
  : 0;

// Priority distribution
const priorityDist = { High: 0, Medium: 0, Low: 0, Error: 0 };
allResults.forEach(item => {
  const priority = item.json.priority || 'Error';
  priorityDist[priority] = (priorityDist[priority] || 0) + 1;
});

// Top opportunities (keywords with high opportunity, low difficulty)
const topOpportunities = successful
  .filter(r => r.difficultyScore < 60 && r.opportunityScore > 50)
  .sort((a, b) => (b.combinedScore || 0) - (a.combinedScore || 0))
  .slice(0, 20)
  .map(r => ({
    keyword: r.keyword,
    difficulty: r.difficultyScore,
    opportunity: r.opportunityScore,
    priority: r.priority,
    combinedScore: r.combinedScore,
    competitorPosition: r.actualPosition,
    competitiveInsight: r.competitiveInsight
  }));

// Competitor strengths (where they rank well)
const competitorStrengths = successful
  .filter(r => r.actualPosition && r.actualPosition <= 5)
  .sort((a, b) => a.actualPosition - b.actualPosition)
  .slice(0, 15)
  .map(r => ({
    keyword: r.keyword,
    position: r.actualPosition,
    difficulty: r.difficultyScore,
    opportunity: r.opportunityScore
  }));

// Competitor weaknesses (where they rank poorly)
const competitorWeaknesses = successful
  .filter(r => r.actualPosition && r.actualPosition > 10)
  .sort((a, b) => (b.opportunityScore || 0) - (a.opportunityScore || 0))
  .slice(0, 15)
  .map(r => ({
    keyword: r.keyword,
    position: r.actualPosition,
    difficulty: r.difficultyScore,
    opportunity: r.opportunityScore
  }));

// Quick wins (low difficulty, competitor not ranking well or at all)
const quickWins = successful
  .filter(r => r.difficultyScore < 50 && r.opportunityScore > 55 && (!r.actualPosition || r.actualPosition > 10))
  .sort((a, b) => (b.opportunityScore || 0) - (a.opportunityScore || 0))
  .slice(0, 10)
  .map(r => r.keyword);

// Long-term targets (high difficulty but high value)
const longTermTargets = successful
  .filter(r => r.difficultyScore >= 60 && r.opportunityScore > 50)
  .sort((a, b) => (b.opportunityScore || 0) - (a.opportunityScore || 0))
  .slice(0, 10)
  .map(r => r.keyword);

// Collect unique related keywords
const allRelatedKeywords = [];
const relatedKeywordSet = new Set();

successful.forEach(result => {
  (result.relatedKeywords || []).forEach(rk => {
    const key = rk.keyword.toLowerCase();
    if (!relatedKeywordSet.has(key)) {
      relatedKeywordSet.add(key);
      allRelatedKeywords.push(rk);
    }
  });
});

// Prepare data for competitive gap analysis AI
const topSerpTitles = [];
successful.slice(0, 30).forEach(result => {
  (result.serpOverview || []).slice(0, 2).forEach(serp => {
    if (serp.title) topSerpTitles.push(serp.title);
  });
});

return {
  domain: config.domain,
  totalKeywordsExtracted: config.totalKeywordsExtracted,
  totalKeywordsAnalyzed: successful.length,
  failedKeywords: failed.length,
  failedList: failed,
  rankingDistribution: rankingDistribution,
  aggregateMetrics: {
    avgDifficulty: parseFloat(avgDifficulty.toFixed(2)),
    avgOpportunity: parseFloat(avgOpportunity.toFixed(2)),
    priorityDistribution: priorityDist
  },
  topOpportunities: topOpportunities,
  competitorStrengths: competitorStrengths,
  competitorWeaknesses: competitorWeaknesses,
  quickWins: quickWins,
  longTermTargets: longTermTargets,
  allRelatedKeywords: allRelatedKeywords.slice(0, 100),
  topSerpTitles: topSerpTitles.slice(0, 50),
  individualResults: successful,
  timestamp: config.timestamp
};

