// Build final competitor analysis report
try {
  const aggregateData = $('Aggregate Results').item.json;
  const aiResponse = $input.item.json;

  // Parse AI response
  let strategy;
  try {
    const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);
    const cleanContent = content.replace(/```(?:json)?\s*([\s\S]*?)```/g, '$1').trim();
    strategy = JSON.parse(cleanContent);
  } catch (parseError) {
    // Fallback strategy
    strategy = {
      competitive_positioning: {
        competitor_strength_level: 'moderate',
        overall_vulnerability: 'medium',
        key_advantages: ['Unable to parse AI response'],
        key_weaknesses: ['Analysis incomplete']
      },
      content_pillars: [],
      gap_opportunities: [],
      competitive_threats: [],
      strategic_recommendations: {
        immediate_actions: ['Review competitor analysis manually'],
        30_day_goals: [],
        90_day_goals: []
      }
    };
  }

  // Build comprehensive report
  const competitorReport = {
    domain: aggregateData.domain,
    analysis_summary: {
      total_keywords_extracted: aggregateData.totalKeywordsExtracted,
      total_keywords_analyzed: aggregateData.totalKeywordsAnalyzed,
      failed_analyses: aggregateData.failedKeywords,
      analysis_timestamp: aggregateData.timestamp
    },
    ranking_overview: {
      distribution: aggregateData.rankingDistribution,
      percentage_top10: parseFloat((
        (aggregateData.rankingDistribution.top3 + aggregateData.rankingDistribution.top10) /
        Math.max(aggregateData.totalKeywordsAnalyzed, 1) * 100
      ).toFixed(2))
    },
    aggregate_scores: aggregateData.aggregateMetrics,
    competitive_positioning: strategy.competitive_positioning || {},
    top_opportunities: aggregateData.topOpportunities,
    quick_wins: aggregateData.quickWins,
    long_term_targets: aggregateData.longTermTargets,
    competitor_strengths: aggregateData.competitorStrengths,
    competitor_weaknesses: aggregateData.competitorWeaknesses,
    content_pillars: strategy.content_pillars || [],
    gap_opportunities: strategy.gap_opportunities || [],
    competitive_threats: strategy.competitive_threats || [],
    strategic_recommendations: strategy.strategic_recommendations || {},
    individual_keyword_results: aggregateData.individualResults.map(r => ({
      keyword: r.keyword,
      competitor_position: r.actualPosition,
      competitive_insight: r.competitiveInsight,
      difficulty_score: r.difficultyScore,
      opportunity_score: r.opportunityScore,
      priority: r.priority,
      combined_score: r.combinedScore,
      serp_features_summary: {
        total_results: (r.serpOverview || []).length,
        high_authority_count: r.authorityMetrics?.highAuthorityCount || 0,
        unique_domains: r.authorityMetrics?.uniqueDomains || 0
      },
      content_gaps_summary: {
        missing_topics: (r.contentGaps?.missingSubtopics || []).length,
        thin_areas: (r.contentGaps?.thinContentAreas || []).length
      }
    })),
    failed_keywords: aggregateData.failedList,
    metadata: {
      workflow_version: '2.1-competitor',
      estimated_cost_usd: parseFloat((aggregateData.totalKeywordsAnalyzed * 0.008).toFixed(2)),
      processing_time_estimate: `${Math.ceil(aggregateData.totalKeywordsAnalyzed / 45)} minutes`
    }
  };

  return competitorReport;

} catch (error) {
  throw new Error(`Competitor report building failed: ${error.message}`);
}
